{"command":"cd /workspace && cat > config/color.go <<'EOF'
package config

import (
	"errors"
	"regexp"
	"strconv"
	"strings"
)

// colorKind tells how a Color is rendered as an SGR parameter.
type colorKind int

const (
	colorNone  colorKind = iota // terminal default (no code at all)
	colorNamed                  // one of the 16 basic colors
	color8Bit                   // 256 color palette
	colorRGB                    // 24bit true color
)

// Color is a foreground / background color of a style.
type Color struct {
	kind    colorKind
	index   int // named: 0-15, 8bit: 0-255
	r, g, b int
}

var errInvalidColor = errors.New("invalid format")

var namedColors = map[string]int{
	"black":        0,
	"red":          1,
	"green":        2,
	"yellow":       3,
	"blue":         4,
	"magenta":      5,
	"cyan":         6,
	"white":        7,
	"lightBlack":   8,
	"lightRed":     9,
	"lightGreen":   10,
	"lightYellow":  11,
	"lightBlue":    12,
	"lightMagenta": 13,
	"lightCyan":    14,
	"lightWhite":   15,
}

var (
	reHexColor  = regexp.MustCompile(`^#([0-9a-fA-F]{2})([0-9a-fA-F]{2})([0-9a-fA-F]{2})$`)
	reRGBColor  = regexp.MustCompile(`(?i)^rgb\((\d{1,3}|0x[0-9a-f]{2}), *(\d{1,3}|0x[0-9a-f]{2}), *(\d{1,3}|0x[0-9a-f]{2})\)$`)
	re8BitColor = regexp.MustCompile(`(?i)^(\d{1,3}|0x[0-9a-f]{1,2})$`)
)

// parseComponent parses a decimal or 0x-prefixed hexadecimal byte value.
func parseComponent(s string) (int, bool) {
	var v uint64
	var err error
	if len(s) > 2 && (strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X")) {
		v, err = strconv.ParseUint(s[2:], 16, 64)
	} else {
		v, err = strconv.ParseUint(s, 10, 64)
	}
	if err != nil || v > 255 {
		return 0, false
	}
	return int(v), true
}

// ParseColor parses the textual representation of a color.
func ParseColor(s string) (Color, error) {
	if s == "" || s == "default" {
		return Color{kind: colorNone}, nil
	}
	if idx, ok := namedColors[s]; ok {
		return Color{kind: colorNamed, index: idx}, nil
	}
	if m := reHexColor.FindStringSubmatch(s); m != nil {
		r, _ := strconv.ParseUint(m[1], 16, 8)
		g, _ := strconv.ParseUint(m[2], 16, 8)
		b, _ := strconv.ParseUint(m[3], 16, 8)
		return Color{kind: colorRGB, r: int(r), g: int(g), b: int(b)}, nil
	}
	if m := reRGBColor.FindStringSubmatch(s); m != nil {
		r, ok1 := parseComponent(m[1])
		g, ok2 := parseComponent(m[2])
		b, ok3 := parseComponent(m[3])
		if ok1 && ok2 && ok3 {
			return Color{kind: colorRGB, r: r, g: g, b: b}, nil
		}
		return Color{}, errInvalidColor
	}
	if m := re8BitColor.FindStringSubmatch(s); m != nil {
		v, ok := parseComponent(m[1])
		if ok {
			return Color{kind: color8Bit, index: v}, nil
		}
		return Color{}, errInvalidColor
	}
	return Color{}, errInvalidColor
}

// UnmarshalYAML implements Unmarshaler.
func (c *Color) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var s string
	if err := unmarshal(&s); err != nil {
		return err
	}
	parsed, err := ParseColor(s)
	if err != nil {
		return err
	}
	*c = parsed
	return nil
}

func (c *Color) code(background bool) string {
	if c == nil {
		return ""
	}
	switch c.kind {
	case colorNamed:
		base := 30
		if background {
			base = 40
		}
		idx := c.index
		if idx >= 8 {
			base += 60
			idx -= 8
		}
		return "\x1b[" + strconv.Itoa(base+idx) + "m"
	case color8Bit:
		lead := "38"
		if background {
			lead = "48"
		}
		return "\x1b[" + lead + ";5;" + strconv.Itoa(c.index) + "m"
	case colorRGB:
		lead := "38"
		if background {
			lead = "48"
		}
		return "\x1b[" + lead + ";2;" + strconv.Itoa(c.r) + ";" + strconv.Itoa(c.g) + ";" + strconv.Itoa(c.b) + "m"
	}
	return ""
}
EOF
cat > config/style.go <<'EOF'
package config

import "strings"

// Style describes the decoration of a kind of line.
type Style struct {
	Hide       *bool  `yaml:"hide,omitempty"`
	Bold       *bool  `yaml:"bold,omitempty"`
	Faint      *bool  `yaml:"faint,omitempty"`
	Italic     *bool  `yaml:"italic,omitempty"`
	Underline  *bool  `yaml:"underline,omitempty"`
	BlinkSlow  *bool  `yaml:"blinkSlow,omitempty"`
	BlinkRapid *bool  `yaml:"blinkRapid,omitempty"`
	Inverse    *bool  `yaml:"inverse,omitempty"`
	Conceal    *bool  `yaml:"conceal,omitempty"`
	CrossOut   *bool  `yaml:"crossOut,omitempty"`
	Frame      *bool  `yaml:"frame,omitempty"`
	Encircle   *bool  `yaml:"encircle,omitempty"`
	Overline   *bool  `yaml:"overline,omitempty"`
	Foreground *Color `yaml:"foreground,omitempty"`
	Background *Color `yaml:"background,omitempty"`
}

const reset = "\x1b[0m"

func truth(b *bool) bool { return b != nil && *b }

// Hidden reports whether lines of the style should be removed.
func (s *Style) Hidden() bool {
	return s != nil && truth(s.Hide)
}

// Prefix returns the escape sequences which start the style.
func (s *Style) Prefix() string {
	if s == nil {
		return ""
	}
	var b strings.Builder
	b.WriteString(s.Background.code(true))
	b.WriteString(s.Foreground.code(false))
	flags := []struct {
		on   *bool
		code string
	}{
		{s.Bold, "\x1b[1m"},
		{s.Faint, "\x1b[2m"},
		{s.Italic, "\x1b[3m"},
		{s.Underline, "\x1b[4m"},
		{s.BlinkSlow, "\x1b[5m"},
		{s.BlinkRapid, "\x1b[6m"},
		{s.Inverse, "\x1b[7m"},
		{s.Conceal, "\x1b[8m"},
		{s.CrossOut, "\x1b[9m"},
		{s.Frame, "\x1b[51m"},
		{s.Encircle, "\x1b[52m"},
		{s.Overline, "\x1b[53m"},
	}
	for _, f := range flags {
		if truth(f.on) {
			b.WriteString(f.code)
		}
	}
	return b.String()
}

// Apply decorates the text with the style.
func (s *Style) Apply(text string) string {
	if s == nil {
		return text
	}
	if truth(s.Hide) {
		return ""
	}
	prefix := s.Prefix()
	if prefix == "" {
		return text
	}
	return prefix + text + reset
}

func mergeStyle(base, over *Style) *Style {
	if over == nil {
		return base
	}
	if base == nil {
		base = &Style{}
	}
	merged := *base
	pick := func(dst **bool, src *bool) {
		if src != nil {
			*dst = src
		}
	}
	pick(&merged.Hide, over.Hide)
	pick(&merged.Bold, over.Bold)
	pick(&merged.Faint, over.Faint)
	pick(&merged.Italic, over.Italic)
	pick(&merged.Underline, over.Underline)
	pick(&merged.BlinkSlow, over.BlinkSlow)
	pick(&merged.BlinkRapid, over.BlinkRapid)
	pick(&merged.Inverse, over.Inverse)
	pick(&merged.Conceal, over.Conceal)
	pick(&merged.CrossOut, over.CrossOut)
	pick(&merged.Frame, over.Frame)
	pick(&merged.Encircle, over.Encircle)
	pick(&merged.Overline, over.Overline)
	if over.Foreground != nil {
		merged.Foreground = over.Foreground
	}
	if over.Background != nil {
		merged.Background = over.Background
	}
	return &merged
}
EOF
echo done"}

