// Package editor rewrites the lines written to a stream.
package editor

import (
	"bytes"
	"io"
	"os"
	"syscall"
	"unsafe"
)

// Editor rewrites one line.  The line given to Edit always ends with "\n";
// the returned text is written as is.
type Editor interface {
	Edit(line string) (string, error)
}

type stream struct {
	writer io.Writer
	editor Editor
	buf    []byte
}

// Stream creates a writer which passes each line written into it through the
// editor before writing it to w.
func Stream(w io.Writer, e Editor) io.WriteCloser {
	return &stream{writer: w, editor: e}
}

func dropCR(data []byte) []byte {
	if len(data) > 0 && data[len(data)-1] == '\r' {
		return data[:len(data)-1]
	}
	return data
}

func (s *stream) writeLines(lines []string) error {
	for _, line := range lines {
		text, err := s.editor.Edit(line + "\n")
		if err != nil {
			return err
		}
		if text == "" {
			continue
		}
		if _, err := io.WriteString(s.writer, text); err != nil {
			return err
		}
	}
	return nil
}

func (s *stream) Write(b []byte) (int, error) {
	s.buf = append(s.buf, b...)
	var lines []string
	for {
		i := bytes.IndexByte(s.buf, '\n')
		if i < 0 {
			break
		}
		lines = append(lines, string(dropCR(s.buf[:i])))
		s.buf = s.buf[i+1:]
	}
	if err := s.writeLines(lines); err != nil {
		return 0, err
	}
	return len(b), nil
}

func (s *stream) Close() error {
	rest := string(dropCR(s.buf))
	s.buf = nil
	return s.writeLines([]string{rest})
}

func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return errno == 0
}

// Colorable reports whether decorated output should be produced.
func Colorable() bool {
	if os.Getenv("RICHGO_FORCE_COLOR") != "" {
		return true
	}
	return isTerminal(os.Stderr.Fd())
}
