// Package test decorates the output of "go test".
package test

import (
	"regexp"
	"strconv"
	"strings"

	"richgo/config"
	"richgo/editor"
)

type kind int

const (
	kindBlank kind = iota
	kindBuild
	kindStart
	kindPass
	kindFail
	kindSkip
	kindCover
)

var longLabels = map[kind]string{
	kindBlank: "",
	kindBuild: "BUILD",
	kindStart: "START",
	kindPass:  "PASS",
	kindFail:  "FAIL",
	kindSkip:  "SKIP",
	kindCover: "COVER",
}

var shortLabels = map[kind]string{
	kindBlank: "",
	kindBuild: "!!",
	kindStart: ">",
	kindPass:  "o",
	kindFail:  "x",
	kindSkip:  "-",
	kindCover: "%",
}

func pad(s string, width int) string {
	if len(s) < width {
		return s + strings.Repeat(" ", width-len(s))
	}
	return s
}

func label(k kind) string {
	if config.C.LabelType == nil {
		return ""
	}
	switch *config.C.LabelType {
	case config.LabelTypeLong:
		return pad(longLabels[k], 5) + "| "
	case config.LabelTypeShort:
		return pad(shortLabels[k], 2) + " "
	}
	return ""
}

var (
	reBuild      = regexp.MustCompile(`(?m)^# ([^ ]*)( \[[^ \[\]]+\])?$`)
	reStart      = regexp.MustCompile(`(?m)^=== RUN   Test.*$`)
	rePass       = regexp.MustCompile(`(?m)^[ \t]*--- PASS: Test.*$`)
	reFail       = regexp.MustCompile(`(?m)^[ \t]*--- FAIL: Test.*$`)
	reSkip       = regexp.MustCompile(`(?m)^[ \t]*--- SKIP: Test.*$`)
	reOkPackage  = regexp.MustCompile(`(?m)^ok[ \t]+([^ \t]+)(?:[ \t]+(?:[\d\.]+\w*|\(cached\)))?(?:[ \t]+(coverage:[ \t]+\d+\.\d+% of statements))?(?:[ \t]+\[no tests to run\])?[ \t]*$`)
	reFailPath   = regexp.MustCompile(`(?m)^FAIL([ \t]+[^ \t]+[ \t]+(?:[\d\.]+\w*|\[build failed\]))$`)
	reNoTest     = regexp.MustCompile(`(?m)^\?[ \t]+([^ \t]+[ \t]+\[no test files\])$`)
	reCoverage   = regexp.MustCompile(`(?m)^coverage: ((\d+)\.\d)% of statements?$`)
	rePassLonely = regexp.MustCompile(`(?m)^PASS[ \t]*$`)
	reFailLonely = regexp.MustCompile(`(?m)^FAIL[ \t]*$`)
	reFilename   = regexp.MustCompile(`([^\s:]+\.go)((?::\d+){1,2})`)
	reEmptyLine  = regexp.MustCompile(`(?m)^\n`)
)

type test struct {
	prevStyle *config.Style
	removals  []*regexp.Regexp
}

// New creates the editor for the output of "go test".
func New() editor.Editor {
	removals := make([]*regexp.Regexp, 0, len(config.C.Removals))
	for _, r := range config.C.Removals {
		removals = append(removals, regexp.MustCompile(r))
	}
	return &test{removals: removals}
}

// replace substitutes every match of re in s with the result of fn, which
// receives the submatches of the match.
func replace(re *regexp.Regexp, s string, fn func(m []string) string) string {
	locs := re.FindAllStringSubmatchIndex(s, -1)
	if locs == nil {
		return s
	}
	var b strings.Builder
	last := 0
	for _, loc := range locs {
		b.WriteString(s[last:loc[0]])
		groups := make([]string, len(loc)/2)
		for i := range groups {
			if loc[2*i] >= 0 {
				groups[i] = s[loc[2*i]:loc[2*i+1]]
			}
		}
		b.WriteString(fn(groups))
		last = loc[1]
	}
	b.WriteString(s[last:])
	return b.String()
}

func leaveTestPrefix() bool {
	return config.C.LeaveTestPrefix != nil && *config.C.LeaveTestPrefix
}

// testName trims the "Test" prefix of the name and indents it by the depth
// of the subtest.
func testName(name string) string {
	if !leaveTestPrefix() {
		name = strings.TrimPrefix(name, "Test")
	}
	return strings.Repeat("  ", strings.Count(name, "/")) + name
}

func (e *test) Edit(line string) (string, error) {
	var processed bool
	var style *config.Style

	result := func(s *config.Style, k kind, content string) string {
		processed = true
		style = s
		return s.Apply(label(k) + content)
	}
	tail := func(prefix string) func(m []string) string {
		return func(m []string) string {
			content := strings.TrimLeft(m[0], " ")
			content = strings.TrimPrefix(content, prefix)
			var s *config.Style
			var k kind
			switch prefix {
			case "--- PASS: ":
				s, k = config.C.PassStyle, kindPass
			case "--- FAIL: ":
				s, k = config.C.FailStyle, kindFail
			default:
				s, k = config.C.SkipStyle, kindSkip
			}
			return result(s, k, testName(content))
		}
	}

	line = replace(reBuild, line, func(m []string) string {
		return result(config.C.BuildStyle, kindBuild, strings.TrimPrefix(m[0], "# "))
	})
	line = replace(reStart, line, func(m []string) string {
		return result(config.C.StartStyle, kindStart, testName(strings.TrimPrefix(m[0], "=== RUN   ")))
	})
	line = replace(rePass, line, tail("--- PASS: "))
	line = replace(reFail, line, tail("--- FAIL: "))
	line = replace(reSkip, line, tail("--- SKIP: "))
	line = replace(reOkPackage, line, func(m []string) string {
		return result(config.C.PassStyle, kindPass, m[1]+" "+m[2])
	})
	line = replace(reFailPath, line, func(m []string) string {
		return result(config.C.FailStyle, kindFail, m[1])
	})
	line = replace(reNoTest, line, func(m []string) string {
		return result(config.C.SkipStyle, kindSkip, m[1])
	})
	line = replace(reCoverage, line, func(m []string) string {
		processed = true
		coverage, err := strconv.Atoi(m[2])
		if err != nil {
			panic(err)
		}
		s := config.C.UncoveredStyle
		if config.C.CoverThreshold != nil && coverage >= *config.C.CoverThreshold {
			s = config.C.CoveredStyle
		}
		bar := strings.Repeat("#", coverage/10) + strings.Repeat("_", 10-coverage/10)
		return s.Apply(label(kindCover) + m[1] + "% [" + bar + "]")
	})
	line = replace(rePassLonely, line, func(m []string) string {
		processed = true
		return config.C.PassPackageStyle.Apply("PASS")
	})
	line = replace(reFailLonely, line, func(m []string) string {
		processed = true
		return config.C.FailPackageStyle.Apply("FAIL")
	})
	prev := e.prevStyle
	line = replace(reFilename, line, func(m []string) string {
		return config.C.FileStyle.Apply(m[1]) + config.C.LineStyle.Apply(m[2]) + prev.Prefix()
	})

	for _, r := range e.removals {
		line = r.ReplaceAllString(line, "")
	}
	line = reEmptyLine.ReplaceAllString(line, "")

	if style != nil {
		e.prevStyle = style
	}
	if line == "" {
		return "", nil
	}
	if processed {
		return line, nil
	}
	if e.prevStyle.Hidden() {
		return "", nil
	}
	content := line
	suffix := ""
	if strings.HasSuffix(content, "\n") {
		content = content[:len(content)-1]
		suffix = "\n"
	}
	return e.prevStyle.Apply(label(kindBlank)+content) + suffix, nil
}
EOF
cat > main.go <<'EOF'
// Command richgo enriches the output of "go test" with text decorations.
package main

import (
	"io"
	"os"
	"os/exec"

	"richgo/config"
	"richgo/editor"
	"richgo/editor/parrot"
	"richgo/editor/test"
)

type factoryFunc func() editor.Editor

func formatWriteCloser(w io.Writer, factory factoryFunc) io.WriteCloser {
	if editor.Colorable() {
		return editor.Stream(w, factory())
	}
	return editor.Stream(w, parrot.New())
}

func main() {
	config.Load()

	var mode string
	if len(os.Args) > 1 {
		mode = os.Args[1]
	}

	var cmd *exec.Cmd
	switch mode {
	case "testfilter":
		cmd = exec.Command("cat", "-")
	default:
		cmd = exec.Command("go", os.Args[1:]...)
	}
	cmd.Stdin = os.Stdin

	switch mode {
	case "test", "testfilter":
		stderr := formatWriteCloser(os.Stderr, test.New)
		defer stderr.Close()
		stdout := formatWriteCloser(os.Stdout, test.New)
		defer stdout.Close()
		cmd.Stderr = stderr
		cmd.Stdout = stdout
	default:
		cmd.Stderr = os.Stderr
		cmd.Stdout = os.Stdout
	}

	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		panic(err)
	}
}
