// Command richgo enriches the output of "go test" with text decorations.
package main

import (
	"io"
	"os"
	"os/exec"

	"richgo/config"
	"richgo/editor"
	"richgo/editor/parrot"
	"richgo/editor/test"
)

type factoryFunc func() editor.Editor

func formatWriteCloser(w io.Writer, factory factoryFunc) io.WriteCloser {
	if editor.Colorable() {
		return editor.Stream(w, factory())
	}
	return editor.Stream(w, parrot.New())
}

func main() {
	config.Load()

	var mode string
	if len(os.Args) > 1 {
		mode = os.Args[1]
	}

	var cmd *exec.Cmd
	switch mode {
	case "testfilter":
		cmd = exec.Command("cat", "-")
	default:
		cmd = exec.Command("go", os.Args[1:]...)
	}
	cmd.Stdin = os.Stdin

	switch mode {
	case "test", "testfilter":
		stderr := formatWriteCloser(os.Stderr, test.New)
		defer stderr.Close()
		stdout := formatWriteCloser(os.Stdout, test.New)
		defer stdout.Close()
		cmd.Stderr = stderr
		cmd.Stdout = stdout
	default:
		cmd.Stderr = os.Stderr
		cmd.Stdout = os.Stdout
	}

	if err := cmd.Run(); err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			os.Exit(exitErr.ExitCode())
		}
		panic(err)
	}
}
